// Sleep function
#include <unistd.h>

#include <string>
#include <iostream>

// Enviornment Inputs
int cop_x = 0;
int cop_y = 0;

int robber_x = 6;
int robber_y = 6;

// Player Inputs
volatile int new_input_ready = 0;
volatile int player_dx = 0;
volatile int player_dy = 0;

// Trace Output
std::string trace = "";

// Build robber random controller so we can get quick traces (5)

void read_inputs() {
    // Wait until the game sets new input
    while (!new_input_ready || (robber_x == cop_x && robber_y == cop_y)) {
        usleep(1000);
    }

    // Apply the player input to robber position
    robber_x += player_dx;
    robber_y += player_dy;

    // Record Trace
    std::string curr_trace = std::string("{\"RobberX\":") + std::to_string(robber_x) +
            ", \"RobberY\": " + std::to_string(robber_y) +
            ", \"CopX\": " + std::to_string(cop_x) +
            ", \"CopY\": " + std::to_string(cop_y) + "}\n";

    std::cout << curr_trace;

    trace += curr_trace;

    // Reset flag
    player_dx = 0;
    player_dy = 0;
    new_input_ready = 0;
}

